        $expectedSourceRelativePath = $this->pathMapper->toSourceRelativePath($testRelativePath);
        $expectedSourcePath = $packageRoot . $this->srcMarker . $expectedSourceRelativePath;

        if (is_file($expectedSourcePath)) {
            return [];
