13	use Toolkit\PhpStan\Rule\Architecture\Dependency\DependencyCallResolver;
14	use Toolkit\PhpStan\Rule\Architecture\Dependency\DependencyPath;
15	use Toolkit\PhpStan\Rule\Architecture\Dependency\DependencyRestrictions;
