19	/**
20	 * Forbids configured symbol and file-reading dependencies between project paths.
21	 *
22	 * @implements Rule<Node>
23	 */
24	final class ForbidDependencyRule implements Rule
25	{
26	    private DependencyPath $paths;
27	
28	    private DependencyRestrictions $restrictions;
29	
30	    private SymbolDependencyResolver $symbols;
31	
32	    private FileDependencyResolver $files;
33	
34	    /**
35	     * @param list<array{from: list<string>, excludeFrom?: list<string>, to: list<string>, excludeTo?: list<string>, allowSameRootDirectory?: bool}> $forbiddenDependencies
36	     * @param array<string, array{position: int, name: string}> $dependencyFileReaders
37	     */
38	    public function __construct(
39	        ReflectionProvider $reflectionProvider,
40	        string $dependencyProjectRoot,
41	        array $forbiddenDependencies = DependencyRestrictions::DEFAULTS,
42	        array $dependencyFileReaders = [],
43	    ) {
44	        $this->paths = new DependencyPath($dependencyProjectRoot);
45	        $this->restrictions = new DependencyRestrictions($this->paths, $forbiddenDependencies);
46	        $calls = new DependencyCallResolver($reflectionProvider);
47	        $this->symbols = new SymbolDependencyResolver($reflectionProvider, $calls);
48	        $this->files = new FileDependencyResolver($calls, $this->paths, $dependencyFileReaders);
49	    }
50	
51	    /**
52	     * @return class-string<Node>
53	     */
54	    public function getNodeType(): string
55	    {
56	        return Node::class;
57	    }
58	
59	    /**
60	     * Reports each resolved forbidden destination once per reference node.
61	     *
62	     * @return list<IdentifierRuleError>
63	     */
64	    public function processNode(Node $node, Scope $scope): array
65	    {
66	        $source = $scope->isInTrait() ? $scope->getTraitReflection()->getFileName() ?? $scope->getFile() : $scope->getFile();
67	        if (!$this->restrictions->checks($source)) {
68	            return [];
69	        }
70	
71	        $errors = [];
72	        $targets = $this->symbols->resolve($node, $scope) + $this->files->resolve($node, $scope);
73	        foreach ($targets as $target => $description) {
74	            $pattern = $this->restrictions->violation($source, $target);
75	            if ($pattern === null) {
76	                continue;
77	            }
78	            $errors[] = RuleErrorBuilder::message(sprintf(
79	                'Forbidden dependency from "%s" to "%s" via %s (target pattern "%s"). Remove the reference or move the referenced code/data to an allowed path.',
80	                $this->paths->display($source),
81	                $this->paths->display($target),
82	                $description,
83	                $pattern,
84	            ))->identifier('customRules.forbiddenDependency')->file($source)->line($node->getStartLine())->build();
85	        }
86	
87	        return $errors;
88	    }
89	}
