21	final class PropertyTestConventionRule implements Rule
22	{
23	    /**
24	     * Creates the rule with the shared test scope detector.
25	     */
26	    public function __construct(private TestClassScope $testClassScope)
27	    {
28	    }
29	
30	    /**
31	     * @return class-string<InClassNode>
32	     */
33	    public function getNodeType(): string
