39	     * @param InClassNode $node
40	     * @return list<IdentifierRuleError>
41	     */
42	    public function processNode(Node $node, Scope $scope): array
43	    {
44	        $class = $node->getOriginalNode();
45	        if (!$class instanceof Class_ || !$this->testClassScope->isPropertyTestClass($scope)) {
46	            return [];
47	        }
48	
49	        $className = $node->getClassReflection()->getName();
50	        $name = $class->name !== null ? $class->name->toString() : '';
51	        $errors = [];
52	        if (!str_contains('/' . str_replace('\\', '/', $scope->getFile()), '/tests/Property/')) {
53	            $errors[] = RuleErrorBuilder::message(sprintf('Move property test class %s to tests/Property/%s.php. Property tests must be stored under tests/Property.', $className, $name))
