58	                ->identifier('customRules.propertyTestClassName')->line($class->getStartLine())->build();
59	        }
60	        if ($class->extends === null || $class->extends->toString() !== 'PHPUnit\\Framework\\TestCase') {
61	            $errors[] = RuleErrorBuilder::message(sprintf('Make property test class %s extend PHPUnit\\Framework\\TestCase directly. Move shared test behavior to collaborators.', $className))
62	                ->identifier('customRules.propertyTestExtends')->line($class->getStartLine())->build();
63	        }
