15	{
16	    /** @readonly */
17	    private SourceUnitTestFileResolver $testFileResolver;
18	
19	    /** @readonly */
20	    private TestMethodFileReader $testMethodFileReader;
21	
22	    /** @readonly */
23	    private PublicMethodTestCoverageErrorBuilder $errorBuilder;
24	
25	    /**
26	     * Creates a public method test coverage validator.
27	     */
28	    public function __construct(
29	        ?SourceUnitTestFileResolver $testFileResolver = null,
30	        ?TestMethodFileReader $testMethodFileReader = null,
31	        ?PublicMethodTestCoverageErrorBuilder $errorBuilder = null,
32	    ) {
33	        $this->testFileResolver = $testFileResolver ?? new SourceUnitTestFileResolver();
34	        $this->testMethodFileReader = $testMethodFileReader ?? new TestMethodFileReader();
35	        $this->errorBuilder = $errorBuilder ?? new PublicMethodTestCoverageErrorBuilder();
36	    }
37	
38	    /**
39	     * @return list<IdentifierRuleError>
40	     */
41	    public function errors(ClassMethod $node, string $sourceFile): array
42	    {
43	        if (!$node->isPublic() || $node->isAbstract()) {
44	            return [];
45	        }
46	
47	        $methodName = $node->name->toString();
48	
49	        if (str_starts_with($methodName, '__')) {
50	            return [];
51	        }
52	
53	        $testFile = $this->testFileResolver->resolve($sourceFile);
54	        if ($testFile === null || !is_file($testFile)) {
55	            return [];
56	        }
57	
58	        $expectedPrefix = 'test' . ucfirst($methodName);
59	        foreach ($this->testMethodFileReader->methodNames($testFile) as $testMethod) {
60	            if (str_starts_with($testMethod, $expectedPrefix)) {
61	                return [];
62	            }
63	        }
64	
65	        return [$this->errorBuilder->build($methodName, $expectedPrefix, $node->getStartLine())];
66	    }
